import json
p='R26-p1.jsonl'
lines=open(p).read().splitlines()
out=[]
for l in lines:
    a=json.loads(l)
    if a['segment_id']=='R26-073' and a['code']=='mv2-original-copied-unmigrated':
        continue
    if a['segment_id']=='R26-014':
        a['quote']="Let's analyze the `getter`, `setter`, and `method` functions."
    if a['segment_id']=='R26-036' and a['code']=='duplicate-identical-tool-call':
        a['quote']='<tool_call read> { "path": "/work/run/out/service_worker.js" }'
    if a['segment_id']=='R26-051':
        a['quote']='"default_popup": "index.html"'
    if a['segment_id']=='R26-052' and a['code']=='verification-gap-never-tested':
        a['quote']='The extension now uses `"manifest_version": 3`, has a valid service worker configuration'
    if a['segment_id']=='R26-064':
        a['quote']='I see what happened. The automated converter probably renamed something.'
    out.append(json.dumps(a,ensure_ascii=False))
open(p,'w').write('\n'.join(out)+'\n')
EOF

